package com.example.textapi.utils;

import org.junit.jupiter.api.BeforeAll;
import static org.junit.jupiter.api.Assertions.assertThrows;
import org.junit.jupiter.api.extension.ExtendWith;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.AfterEach;

import org.mockito.Mockito;
import org.mockito.Mock;
import static org.mockito.Mockito.mock;
import org.mockito.junit.jupiter.MockitoExtension;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

public class TextConversionUtilGeneratedAiTests {

    @BeforeEach
    public void setUp() {
        // No state to reset in the utility class
    }

    @Test
    public void convertJsonToYaml_withValidJson_returnsYamlString() {
        // GIVEN a valid JSON string
        String json = "{\"name\":\"John\", \"age\":30}";

        // WHEN converting JSON to YAML
        String yaml = TextConversionUtil.convertJsonToYaml(json);

        // THEN the output should be a non-empty YAML string containing expected keys
        assertNotNull(yaml);
        assertFalse(yaml.isEmpty());
        assertTrue(yaml.contains("name: \"John\"") || yaml.contains("name: John"));
        assertTrue(yaml.contains("age: 30"));
    }

    @Test
    public void convertJsonToYaml_withInvalidJson_returnsErrorMessage() {
        // GIVEN an invalid JSON string
        String invalidJson = "{name:John, age:30"; // missing quotes and closing brace

        // WHEN converting JSON to YAML
        String result = TextConversionUtil.convertJsonToYaml(invalidJson);

        // THEN the output should be an error message containing "Error converting JSON to YAML"
        assertNotNull(result);
        assertTrue(result.startsWith("Error converting JSON to YAML"));
    }

    @Test
    public void convertJsonToXml_withValidJson_returnsXmlString() {
        // GIVEN a valid JSON string
        String json = "{\"name\":\"John\", \"age\":30}";

        // WHEN converting JSON to XML
        String xml = TextConversionUtil.convertJsonToXml(json);

        // THEN the output should be a non-empty XML string containing expected tags
        assertNotNull(xml);
        assertFalse(xml.isEmpty());
        assertTrue(xml.contains("<name>John</name>"));
        assertTrue(xml.contains("<age>30</age>"));
    }

    @Test
    public void convertJsonToXml_withInvalidJson_returnsErrorMessage() {
        // GIVEN an invalid JSON string
        String invalidJson = "{name:John, age:30"; // missing quotes and closing brace

        // WHEN converting JSON to XML
        String result = TextConversionUtil.convertJsonToXml(invalidJson);

        // THEN the output should be an error message containing "Error converting JSON to XML"
        assertNotNull(result);
        assertTrue(result.startsWith("Error converting JSON to XML"));
    }
}

